function localizeRenderedUI(root=app){
  if(language!=='ru'||!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){const raw=node.nodeValue;const trim=raw.trim(),translated=UI_PHRASES[trim];if(translated&&translated!==trim)node.nodeValue=raw.replace(trim,translated)}
  root.querySelectorAll('[placeholder],[aria-label]').forEach(el=>{for(const attr of ['placeholder','aria-label']){const value=el.getAttribute(attr);const translated=UI_PHRASES[value];if(translated&&translated!==value)el.setAttribute(attr,translated)}});
}
if(language==='ru')new MutationObserver(()=>localizeRenderedUI()).observe(app,{childList:true,subtree:true,characterData:true});
tg?.ready();
applyTheme();
applyLanguage();

const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));
const ago = value => { if (!value) return '—'; const seconds = Math.max(0, Date.now()/1000-value); const suffix=language==='ru'?' назад':' ago'; return seconds<60?`${Math.round(seconds)}s${suffix}`:seconds<3600?`${Math.round(seconds/60)}m${suffix}`:new Date(value*1000).toLocaleString(language==='ru'?'ru-RU':'en-US'); };
const bytes = value => { value=Number(value)||0; const units=['B','KiB','MiB','GiB','TiB']; let i=0; while(value>=1024&&i<units.length-1){value/=1024;i++} return `${value>=100?value.toFixed(0):value.toFixed(1)} ${units[i]}`; };
const rate = value => { value=(Number(value)||0)*8; const units=['bit/s','Kbit/s','Mbit/s','Gbit/s']; let i=0; while(value>=1000&&i<units.length-1){value/=1000;i++} return `${value>=100?value.toFixed(0):value.toFixed(1)} ${units[i]}`; };
const diskRate = value => `${bytes(value)}/s`;
async function api(path, options={}) { const response=await fetch(path,{...options,credentials:'same-origin',headers:{...options.headers,'X-Telegram-InitData':initData}}); let data={}; try{data=await response.json()}catch{} if(!response.ok)throw Error(data.error||`HTTP ${response.status}`); return data; }
function note(text){toast.textContent=text;toast.classList.remove('hidden');setTimeout(()=>toast.classList.add('hidden'),3500)}
function clearWork(){clearInterval(state.timer);clearInterval(state.live);state.timer=state.live=null}
function setPage(page){clearWork();state.page=page;document.querySelectorAll('[data-primary-nav] [data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===page));render()}
function resourceTone(percent){return Number(percent)>75?'high':Number(percent)>=50?'warning':'low'}
function networkTone(bytes){return Number(bytes)>=200*1024*1024*1024?'high':'low'}
function status(value){return `<span class="status"><i class="dot ${esc(value)}"></i>${esc(t(String(value)))}</span>`}
function cardAction(command,title,detail){return `<button class="action" data-run="${command}"><b>${esc(title)}</b><small>${esc(detail)}</small></button>`}
function incidentCard(item){return `<div class="card incident ${esc(item.severity)}"><div class="row"><div><b>${esc(item.type)}</b><br><span class="muted tiny">#${item.id} · ${esc(t(item.severity))} · ${esc(t(item.status))} · ${ago(item.last_seen_at)}</span></div><button class="link" data-incident="${item.id}">${t('details')}</button></div></div>`}
function runRow(item){return `<div class="card"><div class="row"><div><b>${esc(item.title)}</b><br><span class="muted tiny">${ago(item.started_at)} · ${item.duration_ms==null?'running':`${item.duration_ms} ms`}</span></div>${status(item.status)}</div></div>`}

async function render(){try{const session=await api('/api/session');if(!session.totp)return login();if(state.page==='dashboard')return dashboard();if(state.page==='metrics')return metrics();if(state.page==='ai')return ai();if(state.page==='events')return events();if(state.page==='activity')return activity();if(state.page==='backups')return backups();if(state.page==='library')return library();if(state.page==='network')return networkTools();if(state.page==='firewall')return firewallPage();if(state.page==='console')return consolePage();if(state.page==='recovery')return recoveryStudio();if(state.page==='intelligence')return stage78Page();return tools()}catch(error){app.innerHTML=`<div class="card empty">${t('authorizationFailed')}: ${esc(error.message)}</div>`}}

function consoleServiceUnit(name){return `${name}.service`}
function openConsole(command){state.consoleCommand=command;setPage('console')}
async function dashboard(){
  const data=await api('/api/dashboard'),system=data.system,counts=data.incident_counts||{};
  const services=(system.services||[]).map(service=>`<button class="service dashboard-action" data-console-run="service ${esc(consoleServiceUnit(service.name))}" aria-label="${esc(t('viewStatus'))}: ${esc(service.name)}"><b>${esc(service.name)}</b><br>${status(service.state)}<small>${t('viewStatus')}</small></button>`).join('');
  const incidents=(data.active_incidents||[]).map(incidentCard).join('')||`<div class="card empty">${t('noActiveIncidents')}</div>`;
  const runs=(data.runs||[]).map(runRow).join('')||`<div class="card empty">${t('noDiagnosticRuns')}</div>`;
  const cpuTone=resourceTone(system.cpu.percent),memoryTone=resourceTone(system.memory.percent),diskTone=resourceTone(system.disk.percent),netTone=networkTone(system.network.bytes_recv);
  app.innerHTML=`<div class="page-kicker"><span>01</span>${t('dashboard')}</div><h1>${esc(system.hostname)}</h1><p class="sub">${t('overview')} · ${system.cpu.cores} CPU core(s)</p><div class="grid four dashboard-grid"><button class="metric tone-${cpuTone} dashboard-action" data-console-run="diagnose cpu" aria-label="${t('openDiagnostic')}: CPU"><label>CPU</label><strong>${system.cpu.percent.toFixed(1)}%</strong><small>Load ${system.cpu.load.map(v=>v.toFixed(2)).join(' / ')}</small><em>${t('openDiagnostic')}</em></button><button class="metric tone-${memoryTone} dashboard-action" data-console-run="diagnose memory" aria-label="${t('openDiagnostic')}: ${t('memory')}"><label>${t('memory')}</label><strong>${system.memory.percent.toFixed(1)}%</strong><small>${bytes(system.memory.available)} ${t('available')}</small><em>${t('openDiagnostic')}</em></button><button class="metric tone-${diskTone} dashboard-action" data-console-run="disk usage" aria-label="${t('openDiagnostic')}: ${t('disk')}"><label>${t('disk')}</label><strong>${system.disk.percent.toFixed(0)}%</strong><small>${bytes(system.disk.free)} ${t('free')}</small><em>${t('openDiagnostic')}</em></button><button class="metric tone-${netTone} dashboard-action" data-console-run="network summary" aria-label="${t('openDiagnostic')}: ${t('networkTraffic')}"><label>${t('networkTraffic')}</label><strong>${bytes(system.network.bytes_recv)}</strong><small>${t('receivedSinceBoot')}</small><em>${t('openDiagnostic')}</em></button></div><div class="dashboard-strip"><button class="primary" data-page-link="metrics">${t('openLiveMetrics')}</button><span class="badge">${counts.active||0} ${t('activeEvents')}</span></div><h2>${t('activeProblems')}</h2>${incidents}<h2>${t('primaryServices')}</h2><p class="sub">${t('serviceHint')}</p><div class="grid four service-grid">${services}</div><h2>${t('recentDiagnostics')}</h2>${runs}`;bind()
}

function formatTime(value, short=false){return new Intl.DateTimeFormat(undefined,short?{hour:'2-digit',minute:'2-digit'}:{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value*1000))}
function drawChart(canvas, points, spec){
  const wrap=canvas.parentElement, tooltip=wrap.querySelector('.tooltip'), rect=canvas.getBoundingClientRect(), dpr=devicePixelRatio||1;
  canvas.width=Math.max(1,rect.width*dpr);canvas.height=Math.max(1,rect.height*dpr);
  const ctx=canvas.getContext('2d'),w=rect.width,h=rect.height,pad={l:50,r:12,t:12,b:27},pw=w-pad.l-pad.r,ph=h-pad.t-pad.b;
  const values=points.flatMap(point=>spec.lines.map(line=>Number(point[line.key])||0));const max=spec.max??Math.max(1,...values)*1.14;
  const y=v=>pad.t+ph-(v/max)*ph;const x=index=>pad.l+(points.length<2?0:index/(points.length-1))*pw;
  function paint(cursorIndex=null){
    ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.font='11px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif';ctx.textBaseline='middle';
    for(let n=0;n<5;n++){const value=max*(1-n/4),pos=pad.t+ph*n/4;ctx.strokeStyle='#263a55';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(pad.l,pos);ctx.lineTo(w-pad.r,pos);ctx.stroke();ctx.fillStyle='#93a6be';ctx.textAlign='right';ctx.fillText(spec.label(value),pad.l-7,pos)}
    ctx.fillStyle='#93a6be';ctx.textAlign='center';for(let n=0;n<4;n++){const index=Math.round(n*(points.length-1)/3),value=points[index]?.time;if(value)ctx.fillText(formatTime(value,spec.shortTime),x(index),h-10)}
    for(const line of spec.lines){ctx.beginPath();points.forEach((point,index)=>{const px=x(index),py=y(Math.min(max,Math.max(0,Number(point[line.key])||0)));index?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.strokeStyle=line.color;ctx.lineWidth=2;ctx.lineJoin='round';ctx.lineCap='round';ctx.stroke()}
    if(cursorIndex!==null){ctx.strokeStyle='#b99aff';ctx.globalAlpha=.92;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x(cursorIndex),pad.t);ctx.lineTo(x(cursorIndex),pad.t+ph);ctx.stroke();ctx.globalAlpha=1}
  }
  function hover(event){const box=canvas.getBoundingClientRect(),clientX=event.touches?event.touches[0].clientX:event.clientX;const index=Math.max(0,Math.min(points.length-1,Math.round((clientX-box.left-pad.l)/pw*(points.length-1))));const point=points[index];if(!point)return;paint(index);const left=Math.max(5,Math.min(box.width-190,clientX-box.left+10));tooltip.style.display='block';tooltip.style.left=`${left}px`;tooltip.style.top='18px';tooltip.innerHTML=`<b>${formatTime(point.time)}</b><br>${spec.tooltip(point).map(item=>`${esc(item.label)}: <b>${esc(item.value)}</b>`).join('<br>')}`}
  function leave(){paint();tooltip.style.display='none'}
  paint();canvas.onmousemove=hover;canvas.ontouchstart=hover;canvas.onmouseleave=leave;canvas.ontouchend=leave;canvas.ontouchcancel=leave;
}
function metricChart(id,title,subtitle,legend){return `<section class="card chart-card"><div class="chart-head"><div class="chart-title"><h3>${title}</h3><small>${subtitle}</small></div><div class="legend">${legend}</div></div><div class="canvas-wrap"><canvas id="${id}" role="img" aria-label="${title} time chart"></canvas><div class="tooltip"></div></div></section>`}
async function metrics(){clearInterval(state.live);clearTimeout(state.timer);const data=await api(`/api/metrics?range=${state.range}`), samples=data.samples||[];state.lastMetricSample=data.last_sample_at;state.metricRefresh=data.refresh_seconds||60;app.innerHTML=`<div class="page-kicker"><span>02</span>${t('metrics')}</div><h1>${t('metrics')}</h1><p class="sub">${t('localTelemetry')} · ${samples.length?`${samples.length} ${t('visualPoints')}`:t('waitingSamples')}</p><div class="metric-toolbar"><div class="controls"><span class="muted">${t('range')}</span>${['1h','6h','24h','7d','30d'].map(item=>`<button class="range ${item===state.range?'selected':''}" data-range="${item}">${item}</button>`).join('')}<span class="live"><i></i><span id="live-state">${t('live')}</span></span><span class="muted tiny" id="refresh-text">${t('checking')}</span><div class="refresh"><i id="refresh-bar"></i></div></div></div>${metricChart('cpu-chart',t('cpuUsage'),t('cpuChartDescription'),`<span><i style="background:#79a8ff"></i>${t('usage')}</span>`)}${metricChart('memory-chart',t('memory'),t('memoryDescription'),`<span><i style="background:#c9a7ff"></i>${t('used')}</span><span><i style="background:#64cde7"></i>${t('cache')}</span><span><i style="background:#67d6a4"></i>${t('available')}</span>`)}${metricChart('network-chart',t('networkTraffic'),t('networkDescription'),'<span><i style="background:#d6a8ff"></i>RX</span><span><i style="background:#b7db75"></i>TX</span>')}${metricChart('disk-chart',t('diskIo'),t('diskDescription'),`<span><i style="background:#64cde7"></i>${t('read')}</span><span><i style="background:#c9a7ff"></i>${t('write')}</span>`)}`;const short=state.range==='1h'||state.range==='6h';drawChart(document.querySelector('#cpu-chart'),samples,{max:100,shortTime:short,label:value=>`${value.toFixed(0)}%`,lines:[{key:'cpu',color:'#79a8ff'}],tooltip:point=>[{label:'CPU',value:`${point.cpu.toFixed(1)}%`},{label:t('loadAverage'),value:point.load1.toFixed(2)}]});drawChart(document.querySelector('#memory-chart'),samples,{shortTime:short,label:bytes,lines:[{key:'mem_used',color:'#c9a7ff'},{key:'mem_cached',color:'#64cde7'},{key:'mem_available',color:'#67d6a4'}],tooltip:point=>[{label:t('used'),value:bytes(point.mem_used)},{label:t('cache'),value:bytes(point.mem_cached)},{label:t('available'),value:bytes(point.mem_available)}]});drawChart(document.querySelector('#network-chart'),samples,{shortTime:short,label:rate,lines:[{key:'rx',color:'#d6a8ff'},{key:'tx',color:'#b7db75'}],tooltip:point=>[{label:'RX',value:rate(point.rx)},{label:'TX',value:rate(point.tx)}]});drawChart(document.querySelector('#disk-chart'),samples,{shortTime:short,label:diskRate,lines:[{key:'read',color:'#64cde7'},{key:'write',color:'#c9a7ff'}],tooltip:point=>[{label:t('read'),value:diskRate(point.read)},{label:t('write'),value:diskRate(point.write)}]});document.querySelectorAll('[data-range]').forEach(button=>button.onclick=()=>{state.range=button.dataset.range;metrics()});startLive();}
function startLive(){const update=()=>{const bar=document.querySelector('#refresh-bar'),label=document.querySelector('#refresh-text'),live=document.querySelector('#live-state');if(!bar||!label||!live)return;const age=state.lastMetricSample?Math.max(0,Date.now()/1000-state.lastMetricSample):Infinity;const period=state.metricRefresh||60;bar.style.width=`${Math.min(100,age/period*100)}%`;if(age>period*2){live.textContent=t('stale');label.textContent=t('waitingCollector')}else{live.textContent=t('live');label.textContent=state.lastMetricSample?`${t('lastSample')} ${Math.round(age)}s ${language==='ru'?'назад':'ago'}`:t('waitingFirstSample')}};update();state.live=setInterval(update,1000);const delay=Math.max(2000,((state.lastMetricSample||Date.now()/1000)+(state.metricRefresh||60)+2-Date.now()/1000)*1000);state.timer=setTimeout(()=>{if(!document.hidden&&state.page==='metrics')metrics()},delay);document.onvisibilitychange=()=>{if(!document.hidden&&state.page==='metrics')metrics()}}


let aiMessages=[], aiController=null;
function ai(){app.innerHTML=`<div class="page-kicker"><span>03</span>${t('aiTitle')}</div><h1>${t('aiTitle')}</h1><p class="sub">${t('aiDescription')}</p><section class="card chat"><div class="row"><h3>${t('newConversation')}</h3><button class="secondary" id="ai-new">${t('newChat')}</button></div><div class="chat-log" id="ai-log"><div class="muted" id="ai-empty">${t('askAgent')}</div></div><div class="chat-compose"><textarea id="ai-input" maxlength="4000" placeholder="${t('writeMessage')}" aria-label="${t('aiTitle')}"></textarea><button class="primary" id="ai-send">${t('send')}</button><button class="danger hidden" id="ai-stop">${t('stop')}</button></div><p class="chat-status" id="ai-status"></p></section>`;document.querySelector('#ai-new').onclick=()=>{aiMessages=[];ai()};document.querySelector('#ai-send').onclick=sendAI;document.querySelector('#ai-stop').onclick=()=>aiController?.abort();document.querySelector('#ai-input').onkeydown=event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();sendAI()}}}
function appendChat(role,content=''){const log=document.querySelector('#ai-log'),empty=document.querySelector('#ai-empty');empty?.remove();const node=document.createElement('div');node.className=`bubble ${role}`;node.textContent=content;log.append(node);log.scrollTop=log.scrollHeight;return node}
async function sendAI(){const input=document.querySelector('#ai-input'),send=document.querySelector('#ai-send'),stop=document.querySelector('#ai-stop'),status=document.querySelector('#ai-status'),text=input.value.trim();if(!text||aiController)return;aiMessages.push({role:'user',content:text});appendChat('user',text);input.value='';const assistant={role:'assistant',content:''};const bubble=appendChat('assistant','');aiController=new AbortController();send.disabled=true;stop.classList.remove('hidden');status.textContent=t('generating');try{const response=await fetch('/api/ai/chat',{method:'POST',headers:{'Content-Type':'application/json','X-Telegram-InitData':initData},body:JSON.stringify({messages:aiMessages}),signal:aiController.signal});if(!response.ok){let failure={};try{failure=await response.json()}catch{}throw Error(failure.error||`HTTP ${response.status}`)}const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});const parts=buffer.split('\n\n');buffer=parts.pop();for(const part of parts){if(!part.startsWith('data: '))continue;const data=part.slice(6);if(data==='[DONE]')continue;const item=JSON.parse(data);if(item.error)throw Error(item.error);assistant.content+=item.delta||'';bubble.textContent=assistant.content;document.querySelector('#ai-log').scrollTop=999999}}if(assistant.content){aiMessages.push(assistant)}else{bubble.remove()}status.textContent=''}catch(error){if(error.name==='AbortError'){if(assistant.content)aiMessages.push(assistant);else bubble.remove();status.textContent=t('generationStopped')}else{aiMessages.pop();bubble.classList.add('error');bubble.textContent=`Error: ${error.message}`;status.textContent=''} }finally{aiController=null;send.disabled=false;stop.classList.add('hidden')}}

async function events(filter='all'){const data=await api(`/api/incidents?status=${filter}`),items=data.incidents||[];app.innerHTML=`<button class="link" data-page-link="tools">${t('backTools')}</button><h1>Server events</h1><p class="sub">Open events are automatically closed on recovery. Closing active events manually may open a new event if the condition persists.</p><div class="controls" style="margin-top:12px"><button class="range ${filter==='all'?'selected':''}" data-event-filter="all">All</button><button class="range ${filter==='open'?'selected':''}" data-event-filter="open">Open</button><button class="range ${filter==='closed'?'selected':''}" data-event-filter="closed">Closed</button>${filter!=='closed'?'<button class="danger" id="close-all">Close all</button>':''}</div>${items.map(incidentCard).join('')||'<div class="card empty">No events in this view.</div>'}`;document.querySelectorAll('[data-event-filter]').forEach(button=>button.onclick=()=>events(button.dataset.eventFilter));const closeAll=document.querySelector('#close-all');if(closeAll)closeAll.onclick=async()=>{if(!confirm('Close all active events? An alert may open again if the problem continues.'))return;try{const result=await api('/api/incidents/close-all',{method:'POST'});note(`Closed ${result.closed} event(s).`);events(filter)}catch(error){note(error.message)}};bind()}
async function openIncident(id){const data=await api(`/api/incidents/${id}`),incident=data.incident,events=(data.events||[]).map(event=>`<div><b>${esc(event.event)}</b><br><span class="muted tiny">${ago(event.time)}</span></div>`).join('');const snapshot=data.snapshot?`<h2>Diagnostic snapshot</h2><pre>${esc(JSON.stringify(data.snapshot,null,2))}</pre>`:'';app.innerHTML=`<button class="link" data-page-link="events">← Server events</button><h1>${esc(incident.type)}</h1><div class="card incident ${esc(incident.severity)}"><b>#${incident.id} · ${esc(incident.severity)} · ${esc(incident.status)}</b><p class="sub">Started ${ago(incident.started_at)} · Last seen ${ago(incident.last_seen_at)}${incident.recovered_at?` · Recovered ${ago(incident.recovered_at)}`:''}</p></div><h2>Timeline</h2><div class="timeline">${events||'<div class="muted">No events.</div>'}</div>${snapshot}<div class="controls" style="margin-top:12px"><button class="secondary" id="incident-investigate">Investigate evidence</button><button class="secondary" id="incident-export">Export anonymized evidence</button></div>`;document.querySelector('#incident-investigate').onclick=async()=>{try{const result=await api(`/api/incidents/${id}/investigate`,{method:'POST'});app.insertAdjacentHTML('beforeend',`<h2>Incident intelligence</h2><pre>${esc(JSON.stringify(result,null,2))}</pre>`)}catch(error){note(error.message)}};document.querySelector('#incident-export').onclick=async()=>{try{const result=await api(`/api/incidents/${id}/forensics`);const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`incident-${id}-evidence.json`;a.click();URL.revokeObjectURL(url)}catch(error){note(error.message)}};bind()}
