async function recoveryStudio(){const data=await api('/api/runbooks');const cards=(data.runbooks||[]).map(item=>`<div class="card"><b>${esc(item.title||item.id)}</b><p class="sub">${esc(item.description||'')}</p><p class="tiny muted">Cooldown ${esc(item.cooldown_seconds||0)}s · attempts ${esc(item.max_attempts||1)}</p><div class="controls"><button class="secondary" data-runbook-dry="${esc(item.id)}">Dry run</button><button class="danger" data-runbook-request="${esc(item.id)}">Request approval</button></div></div>`).join('')||'<div class="card empty">No valid runbooks.</div>';app.innerHTML=`<button class="link" data-page-link="tools">${t('backTools')}</button><h1>Recovery Studio</h1><p class="sub">Runbooks only run fixed diagnostics. Actions require an explicit approval and continue through the existing privileged confirmation path.</p>${cards}<h2>Recent runbook activity</h2>${(data.runs||[]).map(item=>`<div class="card"><b>${esc(item.runbook_id)}</b><br><span class="muted tiny">${esc(item.status)} · ${ago(item.created_at)}</span></div>`).join('')||'<div class="card empty">No runbook runs.</div>'}`;document.querySelectorAll('[data-runbook-dry]').forEach(button=>button.onclick=async()=>{try{const result=await api(`/api/runbooks/${button.dataset.runbookDry}/dry-run`,{method:'POST'});app.insertAdjacentHTML('beforeend',`<h2>Dry-run evidence</h2><pre>${esc(JSON.stringify(result,null,2))}</pre>`)}catch(error){note(error.message)}});document.querySelectorAll('[data-runbook-request]').forEach(button=>button.onclick=async()=>{if(!confirm('Create a recovery request after a fresh TOTP check?'))return;try{const result=await api(`/api/runbooks/${button.dataset.runbookRequest}/request`,{method:'POST'});note(`Recovery request: ${result.status}`);recoveryStudio()}catch(error){note(error.message)}});bind()}

